{"file_path": "mysql-wire.mjs", "content": "#!/usr/bin/env node
/**
 * 零依赖 MySQL 客户端（只用 Node 内置模块）。
 *
 * 只实现本示例需要的子集：
 * - 协议 4.1 握手，支持 mysql_native_password / caching_sha2_password / sha256_password / mysql_clear_password；
 * - caching_sha2_password 的完整认证（over TLS 发明文，或向服务端要 RSA 公钥加密）；
 * - 文本协议 COM_QUERY（单条语句），解析结果集，可选 TLS；
 * - 客户端侧参数占位（?）转义，不拼裸字符串。
 *
 * 不依赖 mysql2，所以 examples/mcp-demo 不需要 npm install 就能跑。
 */

import net from 'node:net'
import tls from 'node:tls'
import { constants as cryptoConstants, createHash, publicEncrypt } from 'node:crypto'

const MAX_PACKET = 0xffffff
const COLLATION_UTF8MB4_GENERAL_CI = 45
const MAX_ROWS_LIMIT = 1000

const CAP = {
  LONG_PASSWORD: 0x00000001,
  FOUND_ROWS: 0x00000002,
  LONG_FLAG: 0x00000004,
  CONNECT_WITH_DB: 0x00000008,
  PROTOCOL_41: 0x00000200,
  SSL: 0x00000800,
  TRANSACTIONS: 0x00002000,
  SECURE_CONNECTION: 0x00008000,
  MULTI_RESULTS: 0x00020000,
  PLUGIN_AUTH: 0x00080000
}

const FIELD = {
  DECIMAL: 0,
  TINY: 1,
  SHORT: 2,
  LONG: 3,
  FLOAT: 4,
  DOUBLE: 5,
  NULL: 6,
  TIMESTAMP: 7,
  LONGLONG: 8,
  INT24: 9,
  DATE: 10,
  TIME: 11,
  DATETIME: 12,
  YEAR: 13,
  NEWDATE: 14,
  VARCHAR: 15,
  BIT: 16,
  NEWDECIMAL: 246
}

/** 文本协议里按数字返回的类型，其余一律给字符串（DECIMAL 保精度也当字符串） */
const NUMERIC_TYPES = new Set([
  FIELD.TINY,
  FIELD.SHORT,
  FIELD.LONG,
  FIELD.LONGLONG,
  FIELD.INT24,
  FIELD.YEAR,
  FIELD.FLOAT,
  FIELD.DOUBLE
])

const UNSIGNED_FLAG = 32

/** 常见错误码 → mysql2 风格的 code，保持示例里的报错可读性 */
const ERROR_CODES = {
  1044: 'ER_DBACCESS_DENIED_ERROR',
  1045: 'ER_ACCESS_DENIED_ERROR',
  1049: 'ER_BAD_DB_ERROR',
  1054: 'ER_BAD_FIELD_ERROR',
  1064: 'ER_PARSE_ERROR',
  1065: 'ER_EMPTY_QUERY',
  1142: 'ER_TABLEACCESS_DENIED_ERROR',
  1146: 'ER_NO_SUCH_TABLE',
  1156: 'ER_NET_PACKETS_OUT_OF_ORDER',
  2013: 'PROTOCOL_CONNECTION_LOST',
  3024: 'ER_QUERY_TIMEOUT'
}

export class MySqlError extends Error {
  constructor({ errno = 0, sqlState = 'HY000', code, message, fatal = false, cause }) {
    super(message, cause ? { cause } : undefined)
    this.name = 'MySqlError'
    this.errno = errno
    this.sqlState = sqlState
    this.code = code ?? ERROR_CODES[errno] ?? (errno ? `ER_${errno}` : 'ER_UNKNOWN')
    this.fatal = fatal
  }
}

/** 把 20 字节的挑战码按字节异或到密码摘要上 */
function xor(a, b) {
  const out = Buffer.allocUnsafe(Math.min(a.length, b.length))
  for (let i = 0; i < out.length; i += 1) out[i] = a[i] ^ b[i]
  return out
}

const sha1 = (data) => createHash('sha1').update(data).digest()
const sha256 = (data) => createHash('sha256').update(data).digest()

/** mysql_native_password：SHA1(password) XOR SHA1(nonce + SHA1(SHA1(password))) */
function nativeScramble(password, nonce) {
  if (!password) return Buffer.alloc(0)
  const pwd = Buffer.from(password, 'utf8')
  const stage1 = sha1(pwd)
  const stage2 = sha1(stage1)
  return xor(stage1, sha1(Buffer.concat([nonce, stage2])))
}

/** caching_sha2_password 快速认证：SHA256(password) XOR SHA256(SHA256(SHA256(password)) + nonce) */
function cachingSha2Scramble(password, nonce) {
  if (!password) return Buffer.alloc(0)
  const pwd = Buffer.from(password, 'utf8')
  const stage1 = sha256(pwd)
  const stage2 = sha256(stage1)
  return xor(stage1, sha256(Buffer.concat([stage2, nonce])))
}

/** 完整认证：把 password\0 与 nonce 异或后用服务端公钥加密 */
function rsaEncryptPassword(password, nonce, publicKeyPem) {
  const plain = Buffer.from(`${password}\0`, 'utf8')
  const scrambled = Buffer.allocUnsafe(plain.length)
  for (let i = 0; i < plain.length; i += 1) scrambled[i] = plain[i] ^ nonce[i % nonce.length]
  return publicEncrypt(
    { key: publicKeyPem, padding: cryptoConstants.RSA_PKCS1_OAEP_PADDING, oaepHash: 'sha1' },
    scrambled
  )
}

function readLenEncInt(buf, offset) {
  const first = buf[offset]
  if (first === undefined) throw new MySqlError({ code: 'PROTOCOL_MALFORMED', message: '读取长度前缀时越界' })
  if (first < 0xfb) return { value: first, length: 1 }
  if (first === 0xfb) return { value: null, length: 1 }
  if (first === 0xfc) return { value: buf.readUInt16LE(offset + 1), length: 3 }
  if (first === 0xfd) return { value: buf.readUIntLE(offset + 1, 3), length: 4 }
  if (first === 0xfe) return { value: Number(buf.readBigUInt64LE(offset + 1)), length: 9 }
  throw new MySqlError({ code: 'PROTOCOL_MALFORMED', message: '非法的长度前缀 0xff' })
}

function readLenEncString(buf, offset) {
  const len = readLenEncInt(buf, offset)
  if (len.value === null) return { value: null, length: len.length }
  const start = offset + len.length
  return { value: buf.toString('utf8', start, start + len.value), length: len.length + len.value }
}

function writeLenEncInt(value) {
  if (value < 0xfb) return Buffer.from([value])
  if (value < 0x10000) {
    const buf = Buffer.allocUnsafe(3)
    buf[0] = 0xfc
    buf.writeUInt16LE(value, 1)
    return buf
  }
  if (value < 0x1000000) {
    const buf = Buffer.allocUnsafe(4)
    buf[0] = 0xfd
    buf.writeUIntLE(value, 1, 3)
    return buf
  }
  const buf = Buffer.allocUnsafe(9)
  buf[0] = 0xfe
  buf.writeBigUInt64LE(BigInt(value), 1)
  return buf
}

const NULL_TERMINATED = (buf, offset) => {
  const end = buf.indexOf(0, offset)
  const stop = end === -1 ? buf.length : end
  return { value: buf.toString('utf8', offset, stop), next: stop + 1 }
}

function nullTerminatedBuffer(buf, offset) {
  const end = buf.indexOf(0, offset)
  const stop = end === -1 ? buf.length : end
  return { value: buf.subarray(offset, stop), next: stop + 1 }
}

function parseErrorPacket(payload) {
  const errno = payload.readUInt16LE(1)
  let offset = 3
  let sqlState = 'HY000'
  if (payload[offset] === 0x23 /* '#' */) {
    sqlState = payload.toString('utf8', offset + 1, offset + 6)
    offset += 6
  }
  return new MySqlError({
    errno,
    sqlState,
    message: payload.toString('utf8', offset) || `MySQL 错误 ${errno}`,
    fatal: true
  })
}

function parseOkPacket(payload) {
  let offset = 1
  const affected = readLenEncInt(payload, offset)
  offset += affected.length
  const insertId = readLenEncInt(payload, offset)
  offset += insertId.length
  const statusFlags = payload.length >= offset + 2 ? payload.readUInt16LE(offset) : 0
  return { affectedRows: affected.value ?? 0, insertId: insertId.value ?? 0, statusFlags }
}

function parseColumnPacket(payload) {
  let offset = 0
  const catalog = readLenEncString(payload, offset)
  offset += catalog.length
  const schema = readLenEncString(payload, offset)
  offset += schema.length
  const table = readLenEncString(payload, offset)
  offset += table.length
  const orgTable = readLenEncString(payload, offset)
  offset += orgTable.length
  const name = readLenEncString(payload, offset)
  offset += name.length
  const orgName = readLenEncString(payload, offset)
  offset += orgName.length
  const fixed = readLenEncInt(payload, offset)
  offset += fixed.length
  const charset = payload.readUInt16LE(offset)
  offset += 2
  const columnLength = payload.readUInt32LE(offset)
  offset += 4
  const type = payload[offset]
  offset += 1
  const flags = payload.readUInt16LE(offset)
  return {
    name: name.value ?? '',
    table: table.value ?? '',
    schema: schema.value ?? '',
    charset,
    columnLength,
    type,
    flags
  }
}

const isEofPacket = (payload) => payload[0] === 0xfe && payload.length < 9

function convertValue(field, raw) {
  if (raw === null) return null
  if (!NUMERIC_TYPES.has(field.type)) return raw
  if (raw === '') return null
  const num = Number(raw)
  if (!Number.isFinite(num)) return raw
  if (field.type === FIELD.FLOAT || field.type === FIELD.DOUBLE) return num
  return field.flags & UNSIGNED_FLAG ? num : num
}

const ESCAPES = {
  '\0': '\\0',
  '\b': '\\b',
  '\t': '\\t',
  '\n': '\\n',
  '\r': '\\r',
  '\x1a': '\\Z',
  '"': '\\"',
  "'": "\\'",
  '\\': '\\\\'
}

function escapeString(value) {
  return `'${value.replace(/[\0\b\t\n\r\x1a"'\\]/g, (ch) => ESCAPES[ch])}'`
}

function formatDate(value) {
  const pad = (n) => String(n).padStart(2, '0')
  const date = `${value.getFullYear()}-${pad(value.getMonth() + 1)}-${pad(value.getDate())}`
  const time = `${pad(value.getHours())}:${pad(value.getMinutes())}:${pad(value.getSeconds())}`
  return `${date} ${time}`
}

function escapeValue(value) {
  if (value === null || value === undefined) return 'NULL'
  if (typeof value === 'number') return Number.isFinite(value) ? String(value) : 'NULL'
  if (typeof value === 'bigint') return value.toString()
  if (typeof value === 'boolean') return value ? '1' : '0'
  if (value instanceof Date) return escapeString(formatDate(value))
  if (Buffer.isBuffer(value)) return `X'${value.toString('hex')}'`
  return escapeString(String(value))
}

/**
 * 把 ? 占位替换成转义后的字面量。
 * 服务端开了 multipleStatements:false，这里也拒绝把值当语句拼进去。
 */
function interpolate(sql, values = []) {
  if (values.length === 0) return sql
  let index = 0
  let out = ''
  for (let i = 0; i < sql.length; i += 1) {
    const ch = sql[i]
    if (ch === '\\') {
      out += sql.slice(i, i + 2)
      i += 1
      continue
    }
    if (ch === "'" || ch === '"') {
      // 跳过字符串字面量里的 ?
      let j = i + 1
      while (j < sql.length) {
        if (sql[j] === '\\') j += 2
        else if (sql[j] === ch) break
        else j += 1
      }
      out += sql.slice(i, j + 1)
      i = j
      continue
    }
    if (ch === '?') {
      if (index >= values.length) throw new MySqlError({ message: 'SQL 里的 ? 占位多于传入的参数' })
      out += escapeValue(values[index])
      index += 1
      continue
    }
    out += ch
  }
  if (index !== values.length) throw new MySqlError({ message: '传入的参数多于 SQL 里的 ? 占位' })
  return out
}

/** 把 TCP 错误包装成带地址信息的可读错误 */
function wrapNetworkError(error, host, port) {
  if (error instanceof MySqlError) return error
  const codes = {
    ECONNREFUSED: `无法连接 ${host}:${port}（连接被拒绝，检查地址/端口/防火墙）`,
    ENOTFOUND: `无法解析主机名 ${host}`,
    EHOSTUNREACH: `主机 ${host} 不可达`,
    ETIMEDOUT: `连接 ${host}:${port} 超时`,
    ECONNRESET: `与 ${host}:${port} 的连接被重置`,
    EPIPE: `与 ${host}:${port} 的连接已断开`
  }
  const code = error?.code ?? 'ECONNRESET'
  return new MySqlError({
    code,
    message: codes[code] ?? `${host}:${port} 网络错误：${error?.message ?? error}`,
    fatal: true,
    cause: error
  })
}

/** 逐帧切包：3 字节小端长度 + 1 字节序号 */
class PacketStream {
  constructor(socket) {
    this.buffer = Buffer.alloc(0)
    this.queue = []
    this.waiter = null
    this.error = null
    this.onData = (chunk) => this.#push(chunk)
    this.onError = (error) => this.fail(error)
    this.onClose = () => this.fail(new MySqlError({ code: 'PROTOCOL_CONNECTION_LOST', message: '连接被服务端关闭', fatal: true }))
    socket.on('data', this.onData)
    socket.on('error', this.onError)
    socket.on('close', this.onClose)
  }

  detach(socket) {
    socket.off('data', this.onData)
    socket.off('error', this.onError)
    socket.off('close', this.onClose)
  }

  #push(chunk) {
    this.buffer = this.buffer.length === 0 ? chunk : Buffer.concat([this.buffer, chunk])
    while (this.buffer.length >= 4) {
      const length = this.buffer.readUIntLE(0, 3)
      if (this.buffer.length < 4 + length) break
      const packet = {
        seq: this.buffer[3],
        payload: this.buffer.subarray(4, 4 + length)
      }
      this.buffer = this.buffer.subarray(4 + length)
      if (this.waiter) {
        const waiter = this.waiter
        this.waiter = null
        waiter.resolve(packet)
      } else {
        this.queue.push(packet)
      }
    }
  }

  fail(error) {
    if (this.error) return
    this.error = error
    if (this.waiter) {
      const waiter = this.waiter
      this.waiter = null
      waiter.reject(error)
    }
  }

  next() {
    if (this.queue.length > 0) return Promise.resolve(this.queue.shift())
    if (this.error) return Promise.reject(this.error)
    return new Promise((resolve, reject) => {
      this.waiter = { resolve, reject }
    })
  }
}

function framePacket(payload, seq) {
  if (payload.length > MAX_PACKET) throw new MySqlError({ message: `单个数据包过大：${payload.length} 字节` })
  const header = Buffer.allocUnsafe(4)
  header.writeUIntLE(payload.length, 0, 3)
  header[3] = seq
  return Buffer.concat([header, payload])
}

export class Connection {
  constructor(settings) {
    this.settings = settings
    this.socket = null
    this.stream = null
    this.seq = 0
    this.closed = false
    this.chain = Promise.resolve()
    this.serverInfo = {}
  }

  /** 连接 + 认证；失败时抛 MySqlError，且保证 socket 已释放 */
  static async open(settings, { connectTimeout = 8000 } = {}) {
    const connection = new Connection(settings)
    try {
      await connection.#handshake(connectTimeout)
      return connection
    } catch (error) {
      connection.destroy()
      throw error instanceof MySqlError ? error : wrapNetworkError(error, settings.host, settings.port)
    }
  }

  async #handshake(connectTimeout) {
    const { host, port, user, password, database, ssl } = this.settings
    const socket = net.connect({ host, port })
    socket.setNoDelay(true)
    this.socket = socket

    await new Promise((resolve, reject) => {
      const onError = (error) => {
        socket.off('connect', onConnect)
        reject(wrapNetworkError(error, host, port))
      }
      const onConnect = () => {
        socket.off('error', onError)
        socket.setTimeout(0)
        resolve()
      }
      socket.once('error', onError)
      socket.once('connect', onConnect)
      socket.setTimeout(connectTimeout, () => {
        socket.destroy()
        reject(new MySqlError({ code: 'ETIMEDOUT', message: `连接 ${host}:${port} 超时（${connectTimeout}ms）`, fatal: true }))
      })
    })

    this.stream = new PacketStream(socket)
    const handshake = await this.stream.next()
    if (handshake.payload[0] === 0xff) throw parseErrorPacket(handshake.payload)

    const greeting = this.#parseHandshake(handshake.payload)
    this.serverInfo = { serverVersion: greeting.serverVersion, threadId: greeting.threadId, authPlugin: greeting.authPlugin }

    let capabilities = CAP.LONG_PASSWORD | CAP.FOUND_ROWS | CAP.LONG_FLAG | CAP.PROTOCOL_41 | CAP.SECURE_CONNECTION | CAP.TRANSACTIONS | CAP.MULTI_RESULTS | CAP.PLUGIN_AUTH
    if (database) capabilities |= CAP.CONNECT_WITH_DB
    capabilities &= greeting.capabilities | CAP.PROTOCOL_41

    let plugin = greeting.authPlugin || 'mysql_native_password'
    let nonce = greeting.nonce
    let secure = false

    if (ssl) {
      if (!(greeting.capabilities & CAP.SSL)) {
        throw new MySqlError({ code: 'HANDSHAKE_SSL_UNSUPPORTED', message: '服务端未开启 SSL，但配置要求 MCP_DB_SSL=true', fatal: true })
      }
      capabilities |= CAP.SSL
      this.seq = handshake.seq + 1
      this.#write(this.#sslRequest(capabilities))
      const secureSocket = await this.#upgradeToTls(host)
      this.stream.detach(socket)
      socket.removeAllListeners('data')
      this.socket = secureSocket
      this.stream = new PacketStream(secureSocket)
      secure = true
    }

    this.seq = ssl ? handshake.seq + 2 : handshake.seq + 1
    this.#write(this.#handshakeResponse({ capabilities, user, password, database, plugin, nonce }))

    await this.#authenticate({ plugin, nonce, password, secure })
    this.seq = 0
  }

  #parseHandshake(payload) {
    let offset = 0
    const protocolVersion = payload[offset]
    offset += 1
    if (protocolVersion !== 10) {
      throw new MySqlError({ code: 'HANDSHAKE_UNSUPPORTED', message: `不支持的握手协议版本 ${protocolVersion}`, fatal: true })
    }
    const version = NULL_TERMINATED(payload, offset)
    offset = version.next
    const threadId = payload.readUInt32LE(offset)
    offset += 4
    const scramble1 = payload.subarray(offset, offset + 8)
    offset += 8
    offset += 1 // filler
    let capabilities = payload.readUInt16LE(offset)
    offset += 2
    let authPluginDataLen = 0
    let authPlugin = ''
    let scramble2 = Buffer.alloc(0)

    if (payload.length > offset) {
      offset += 1 // charset
      offset += 2 // status flags
      capabilities |= payload.readUInt16LE(offset) << 16
      offset += 2
      authPluginDataLen = payload[offset]
      offset += 1
      offset += 10 // reserved
      if (capabilities & CAP.SECURE_CONNECTION) {
        const part2Len = authPluginDataLen > 0 ? Math.max(13, authPluginDataLen - 8) : 13
        scramble2 = nullTerminatedBuffer(payload, offset).value
        offset += part2Len
      }
      if (capabilities & CAP.PLUGIN_AUTH && payload.length > offset) {
        authPlugin = NULL_TERMINATED(payload, offset).value
      }
    }

    const nonce = Buffer.concat([scramble1, scramble2]).subarray(0, 20)
    return { protocolVersion, serverVersion: version.value, threadId, capabilities, nonce, authPlugin }
  }

  #sslRequest(capabilities) {
    const payload = Buffer.alloc(32)
    payload.writeUInt32LE(capabilities, 0)
    payload.writeUInt32LE(0x01000000, 4) // max packet size 16MB
    payload[8] = COLLATION_UTF8MB4_GENERAL_CI
    return Buffer.concat([payload, Buffer.alloc(23)])
  }

  async #upgradeToTls(host) {
    const { insecureTls = false } = this.settings
    return new Promise((resolve, reject) => {
      const secureSocket = tls.connect(
        {
          socket: this.socket,
          servername: net.isIP(host) ? undefined : host,
          rejectUnauthorized: !insecureTls
        },
        () => {
          secureSocket.setNoDelay(true)
          resolve(secureSocket)
        }
      )
      secureSocket.once('error', (error) => {
        reject(wrapNetworkError(error, host, this.settings.port))
      })
    })
  }

  #handshakeResponse({ capabilities, user, password, database, plugin, nonce }) {
    const authResponse = this.#authResponseFor(plugin, password, nonce, false)
    const parts = []
    const head = Buffer.alloc(32)
    head.writeUInt32LE(capabilities, 0)
    head.writeUInt32LE(0x01000000, 4)
    head[8] = COLLATION_UTF8MB4_GENERAL_CI
    parts.push(head)
    parts.push(Buffer.from(`${user}\0`, 'utf8'))
    if (capabilities & CAP.SECURE_CONNECTION) {
      parts.push(Buffer.from([authResponse.length]))
      parts.push(authResponse)
    } else {
      parts.push(authResponse)
      parts.push(Buffer.from([0]))
    }
    if (capabilities & CAP.CONNECT_WITH_DB) parts.push(Buffer.from(`${database}\0`, 'utf8'))
    if (capabilities & CAP.PLUGIN_AUTH) parts.push(Buffer.from(`${plugin}\0`, 'utf8'))
    return Buffer.concat(parts)
  }

  #authResponseFor(plugin, password, nonce, secure) {
    switch (plugin) {
      case 'mysql_native_password':
        return nativeScramble(password, nonce)
      case 'caching_sha2_password':
      case 'sha256_password':
        return cachingSha2Scramble(password, nonce)
      case 'mysql_clear_password':
        return Buffer.from(`${password}\0`, 'utf8')
      default:
        // 未知插件：over TLS 尝试明文，否则交给 auth switch 处理
        if (secure) return Buffer.from(`${password}\0`, 'utf8')
        return nativeScramble(password, nonce)
    }
  }

  async #authenticate({ plugin, nonce, password, secure }) {
    let currentPlugin = plugin
    let currentNonce = nonce
    for (let round = 0; round < 5; round += 1) {
      const packet = await this.stream.next()
      const type = packet.payload[0]

      if (type === 0x00) {
        this.seq = 0
        return
      }
      if (type === 0xff) throw parseErrorPacket(packet.payload)

      if (type === 0xfe) {
        // Auth Switch Request：服务端指定新的插件和新的挑战码
        const requested = NULL_TERMINATED(packet.payload, 1)
        currentPlugin = requested.value || 'mysql_native_password'
        currentNonce = nullTerminatedBuffer(packet.payload, requested.next).value.subarray(0, 20)
        this.#write(this.#authResponseFor(currentPlugin, password, currentNonce, secure))
        continue
      }

      if (type === 0x01) {
        const marker = packet.payload[1]
        if (currentPlugin === 'caching_sha2_password') {
          if (marker === 0x03) continue // 快速认证成功，等 OK
          if (marker === 0x04) {
            // 完整认证：TLS 下直接发明文，否则要公钥做 RSA 加密
            if (secure) {
              this.#write(Buffer.from(`${password}\0`, 'utf8'))
              continue
            }
            this.#write(Buffer.from([0x02]))
            const keyPacket = await this.stream.next()
            if (keyPacket.payload[0] === 0xff) throw parseErrorPacket(keyPacket.payload)
            const pem = keyPacket.payload.subarray(1).toString('utf8')
            this.#write(rsaEncryptPassword(password, currentNonce, pem))
            continue
          }
        }
        if (currentPlugin === 'sha256_password') {
          if (secure) {
            this.#write(Buffer.from(`${password}\0`, 'utf8'))
            continue
          }
          this.#write(Buffer.from([0x01]))
          const keyPacket = await this.stream.next()
          if (keyPacket.payload[0] === 0xff) throw parseErrorPacket(keyPacket.payload)
          const pem = keyPacket.payload.subarray(1).toString('utf8')
          this.#write(rsaEncryptPassword(password, currentNonce, pem))
          continue
        }
        throw new MySqlError({ code: 'HANDSHAKE_UNSUPPORTED', message: `插件 ${currentPlugin} 要求了不支持的认证步骤`, fatal: true })
      }

      throw new MySqlError({ code: 'PROTOCOL_MALFORMED', message: `认证阶段收到未知包类型 0x${type.toString(16)}`, fatal: true })
    }
    throw new MySqlError({ code: 'HANDSHAKE_UNSUPPORTED', message: '认证交互次数过多，已放弃', fatal: true })
  }

  #write(payload) {
    if (this.closed || !this.socket) throw new MySqlError({ code: 'PROTOCOL_CONNECTION_LOST', message: '连接已关闭', fatal: true })
    this.socket.write(framePacket(payload, this.seq))
    this.seq = (this.seq + 1) & 0xff
  }

  /**
   * 执行一条语句（同一连接上串行）。
   * @returns {Promise<{ rows: object[], fields: object[], affectedRows: number, insertId: number }>}
   */
  query(sql, values = [], { timeout = 15000 } = {}) {
    const run = () => this.#queryWithTimeout(interpolate(sql, values), timeout)
    const next = this.chain.then(run, run)
    this.chain = next.then(
      () => undefined,
      () => undefined
    )
    return next
  }

  async #queryWithTimeout(sql, timeout) {
    if (this.closed) throw new MySqlError({ code: 'PROTOCOL_CONNECTION_LOST', message: '连接已关闭', fatal: true })
    let timer
    const timeoutError = new MySqlError({ code: 'ER_QUERY_TIMEOUT', errno: 3024, message: `查询超时（${timeout}ms）`, fatal: true })
    const guard = new Promise((_, reject) => {
      timer = setTimeout(() => {
        this.destroy()
        reject(timeoutError)
      }, timeout)
    })
    try {
      return await Promise.race([this.#runQuery(sql), guard])
    } finally {
      clearTimeout(timer)
    }
  }

  async #runQuery(sql) {
    this.seq = 0
    this.#write(Buffer.concat([Buffer.from([0x03]), Buffer.from(sql, 'utf8')]))
    const first = await this.stream.next()
    const head = first.payload

    if (head[0] === 0x00) {
      const ok = parseOkPacket(head)
      this.seq = 0
      return { rows: [], fields: [], affectedRows: ok.affectedRows, insertId: ok.insertId }
    }
    if (head[0] === 0xff) throw parseErrorPacket(head)
    if (head[0] === 0xfb) {
      throw new MySqlError({ code: 'LOAD_INFILE_UNSUPPORTED', message: '服务端要求 LOCAL INFILE，本客户端不支持' })
    }

    const count = readLenEncInt(head, 0)
    const columnCount = count.value ?? 0
    const fields = []
    for (let i = 0; i < columnCount; i += 1) {
      const packet = await this.stream.next()
      fields.push(parseColumnPacket(packet.payload))
    }

    let packet = await this.stream.next()
    if (!isEofPacket(packet.payload)) {
      // 有些服务端在列定义后不发 EOF（DEPRECATE_EOF），把这一包当第一行数据
      const rows = [this.#parseRow(packet.payload, fields)]
      return { rows: [...rows, ...(await this.#readRows(fields))], fields, affectedRows: 0, insertId: 0 }
    }
    const rows = await this.#readRows(fields)
    this.seq = 0
    return { rows, fields, affectedRows: 0, insertId: 0 }
  }

  async #readRows(fields) {
    const rows = []
    while (true) {
      const packet = await this.stream.next()
      if (packet.payload[0] === 0xff) throw parseErrorPacket(packet.payload)
      if (isEofPacket(packet.payload)) break
      if (rows.length >= MAX_ROWS_LIMIT) continue // 兜底丢弃，避免恶意大结果撑爆内存
      rows.push(this.#parseRow(packet.payload, fields))
    }
    return rows
  }

  #parseRow(payload, fields) {
    const row = {}
    let offset = 0
    for (const field of fields) {
      if (payload[offset] === 0xfb) {
        row[field.name] = null
        offset += 1
        continue
      }
      const cell = readLenEncString(payload, offset)
      offset += cell.length
      row[field.name] = convertValue(field, cell.value)
    }
    return row
  }

  destroy() {
    if (this.closed) return
    this.closed = true
    if (this.stream && this.socket) this.stream.detach(this.socket)
    if (this.socket) {
      this.socket.destroy()
      this.socket = null
    }
    if (this.stream) this.stream.fail(new MySqlError({ code: 'PROTOCOL_CONNECTION_LOST', message: '连接已关闭', fatal: true }))
  }

  /** 优雅关闭：先发 COM_QUIT，再断 socket */
  async end() {
    if (this.closed) return
    try {
      this.seq = 0
      this.#write(Buffer.from([0x01]))
    } catch {
      // 已经断了就直接销毁
    }
    const socket = this.socket
    this.destroy()
    if (socket) await new Promise((resolve) => socket.once('close', resolve).end(() => resolve()))
  }
}

/** 便捷包装：按 settings 打开一条连接 */
export function connect(settings, options) {
  return Connection.open(settings, options)
}

export const internals = { interpolate, escapeValue, nativeScramble, cachingSha2Scramble, writeLenEncInt, FIELD, CAP }
"}

{"content": "#!/usr/bin/env node
/**
 * 零依赖的 MCP stdio 服务端骨架（只用 Node 内置模块）。
 *
 * 只实现 scoder 用到的最小能力：
 * - initialize / notifications/initialized / ping / tools/list / tools/call
 * - stdio 传输：一行一条 JSON-RPC 消息（stdout 只放协议数据，日志一律走 stderr）
 *
 * 用法：
 *   const server = createServer({ name, version, instructions, tools })
 *   server.start()
 */

import { createInterface } from 'node:readline'

/** 支持的协议版本，按新到旧排列；客户端请求其中任意一个就原样回它 */
const PROTOCOL_VERSIONS = ['2025-06-18', '2025-03-26', '2024-11-05']
const FALLBACK_VERSION = '2024-11-05'

const JSONRPC_PARSE_ERROR = -32700
const JSONRPC_INVALID_REQUEST = -32600
const JSONRPC_METHOD_NOT_FOUND = -32601
const JSONRPC_INTERNAL_ERROR = -32603

function log(...args) {
  // stdio 传输下 stdout 是协议通道，任何日志都必须写 stderr
  console.error(...args)
}

class RpcError extends Error {
  constructor(code, message, data) {
    super(message)
    this.code = code
    this.data = data
  }
}

/**
 * @param {object} options
 * @param {string} options.name 服务端名（出现在 initialize 结果里）
 * @param {string} options.version
 * @param {string} [options.instructions] 会作为 instructions 返回给客户端
 * @param {Array<{name: string, description: string, inputSchema: object}>} options.tools
 * @param {(name: string, args: object) => Promise<object>|object} options.callTool
 *       返回 { content: [{ type: 'text', text }] }，失败返回 { isError: true, content: [...] }
 */
export function createServer({ name, version, instructions, tools = [], callTool }) {
  const toolNames = new Set(tools.map((tool) => tool.name))
  let initialized = false

  async function handleRequest(method, params) {
    switch (method) {
      case 'initialize': {
        const requested = params?.protocolVersion
        const protocolVersion = PROTOCOL_VERSIONS.includes(requested) ? requested : FALLBACK_VERSION
        initialized = true
        return {
          protocolVersion,
          capabilities: { tools: { listChanged: false } },
          serverInfo: { name, version },
          ...(instructions ? { instructions } : {})
        }
      }
      case 'ping':
        return {}
      case 'tools/list':
        return { tools }
      case 'tools/call': {
        const toolName = params?.name
        if (typeof toolName !== 'string' || !toolNames.has(toolName)) {
          throw new RpcError(JSONRPC_INVALID_REQUEST, `未知工具：${toolName ?? '(未提供)'}`)
        }
        const args = params?.arguments ?? {}
        // callTool 约定的返回值直接作为 MCP 的 tools/call result
        return await callTool(toolName, args)
      }
      default:
        throw new RpcError(JSONRPC_METHOD_NOT_FOUND, `不支持的方法：${method}`)
    }
  }

  function send(message) {
    process.stdout.write(`${JSON.stringify(message)}\n`)
  }

  async function handleMessage(raw) {
    const line = raw.trim()
    if (line.length === 0) return

    let message
    try {
      message = JSON.parse(line)
    } catch (error) {
      send({ jsonrpc: '2.0', id: null, error: { code: JSONRPC_PARSE_ERROR, message: `JSON 解析失败：${error.message}` } })
      return
    }

    if (Array.isArray(message)) {
      send({ jsonrpc: '2.0', id: null, error: { code: JSONRPC_INVALID_REQUEST, message: '不支持批量请求' } })
      return
    }
    if (message?.jsonrpc !== '2.0' || typeof message.method !== 'string') {
      if (message && 'id' in message) {
        send({ jsonrpc: '2.0', id: message.id ?? null, error: { code: JSONRPC_INVALID_REQUEST, message: '不是合法的 JSON-RPC 2.0 请求' } })
      }
      return
    }

    const isNotification = !('id' in message) || message.id === null || message.id === undefined

    // 通知不需要响应
    if (isNotification) {
      if (message.method === 'notifications/initialized') log('[mcp] 客户端已完成初始化')
      return
    }

    try {
      const result = await handleRequest(message.method, message.params)
      send({ jsonrpc: '2.0', id: message.id, result })
    } catch (error) {
      const code = error instanceof RpcError ? error.code : JSONRPC_INTERNAL_ERROR
      const text = error instanceof Error ? error.message : String(error)
      if (!(error instanceof RpcError)) log(`[mcp] ${message.method} 处理失败：${text}`)
      send({
        jsonrpc: '2.0',
        id: message.id,
        error: { code, message: text, ...(error?.data ? { data: error.data } : {}) }
      })
    }
  }

  function start() {
    const rl = createInterface({ input: process.stdin, crlfDelay: Infinity })
    rl.on('line', (line) => {
      void handleMessage(line)
    })
    rl.on('close', () => {
      log('[mcp] stdin 已关闭，服务端退出')
      process.exit(0)
    })
    return { initialized: () => initialized }
  }

  return { start, handleRequest }
}

export { PROTOCOL_VERSIONS, RpcError }
", "file_path": "mcp-stdio.mjs"}

{"content": "#!/usr/bin/env node
/**
 * scoder MCP 示例（stdio）：远程只读 MySQL —— 零依赖版本。
 *
 * 和 mysql-server.mjs 的功能、工具清单、环境变量完全一致，区别是**不需要 npm install**：
 * MCP 协议用 mcp-stdio.mjs，MySQL 协议用 mysql-wire.mjs，两者都只依赖 Node 内置模块。
 *
 * 必填环境变量：MCP_DB_HOST / MCP_DB_USER / MCP_DB_NAME
 * 可选环境变量：MCP_DB_PORT（默认 3306）、MCP_DB_PASSWORD、
 *               MCP_DB_SSL（true/false）、MCP_DB_SSL_INSECURE（1 表示跳过证书校验）、
 *               MCP_DB_QUERY_TIMEOUT_MS（默认 15000）
 *
 * 安全边界与官方 SDK 版本一致：只读工具、只允许单条 SELECT / WITH、最多 100 行、
 * 单次查询有超时；真正的兜底仍然是数据库账号只授予 SELECT。
 */

import { createServer } from './mcp-stdio.mjs'
import { Connection, MySqlError } from './mysql-wire.mjs'

const MAX_ROWS = 100
const MAX_TEXT_CHARS = 20_000
const CONNECT_TIMEOUT_MS = 8_000

/** 查询超时：1s - 60s，非法值回退到 15s */
function queryTimeoutMs() {
  const value = Number(process.env.MCP_DB_QUERY_TIMEOUT_MS ?? 15_000)
  if (!Number.isFinite(value) || value < 1_000 || value > 60_000) return 15_000
  return Math.trunc(value)
}

const QUERY_TIMEOUT_MS = queryTimeoutMs()

/** 读取并校验连接配置；缺少必填项时给出可操作的错误 */
function connectionSettings() {
  const host = process.env.MCP_DB_HOST?.trim()
  const user = process.env.MCP_DB_USER?.trim()
  const database = process.env.MCP_DB_NAME?.trim()
  if (!host || !user || !database) {
    throw new Error(
      '缺少数据库连接配置：请在 scoder 的 MCP 环境变量里填写 MCP_DB_HOST、MCP_DB_USER、MCP_DB_NAME'
    )
  }

  const port = Number(process.env.MCP_DB_PORT ?? 3306)
  if (!Number.isInteger(port) || port < 1 || port > 65_535) {
    throw new Error(`MCP_DB_PORT 不合法：${process.env.MCP_DB_PORT}`)
  }

  const useSsl = process.env.MCP_DB_SSL === 'true'
  const insecure = process.env.MCP_DB_SSL_INSECURE === '1'

  return {
    host,
    port,
    user,
    password: process.env.MCP_DB_PASSWORD ?? '',
    database,
    ssl: useSsl,
    // 默认校验证书；只有显式设置 MCP_DB_SSL_INSECURE=1 才跳过（仅限自签名测试环境）
    insecureTls: insecure
  }
}

let connection

/**
 * 延迟建连：只配置、不调用工具时不会去连数据库。
 * 连接断掉（服务端重启、网络抖动、查询超时被销毁）后下一次调用会自动重连一次。
 */
async function getConnection() {
  if (connection && !connection.closed) return connection
  const settings = connectionSettings()
  connection = await Connection.open(settings, { connectTimeout: CONNECT_TIMEOUT_MS })
  return connection
}

/** 执行一条查询；连接级失败时重连一次再试 */
async function run(sql, values = []) {
  const first = await getConnection()
  try {
    return await first.query(sql, values, { timeout: QUERY_TIMEOUT_MS })
  } catch (error) {
    if (!(error instanceof MySqlError) || !error.fatal) throw error
    first.destroy()
    if (connection === first) connection = undefined
    const retry = await getConnection()
    return retry.query(sql, values, { timeout: QUERY_TIMEOUT_MS })
  }
}

/** 写操作关键字：宁可误拒，也不让这个示例变成写入口 */
const WRITE_KEYWORD =
  /\b(insert|update|delete|replace|drop|alter|create|truncate|rename|grant|revoke|load_file|outfile|dumpfile|sleep|benchmark|for\s+update|lock\s+in\s+share\s+mode)\b/i

/**
 * 把模型给的 SQL 收紧成一条只读查询。
 * 返回包了一层 LIMIT 的 SQL，行数上限由服务端强制。
 */
function readOnlySql(raw) {
  if (typeof raw !== 'string' || raw.trim().length === 0) {
    throw new Error('sql 不能为空')
  }

  let sql = raw.trim()
  if (sql.endsWith(';')) sql = sql.slice(0, -1).trim()
  if (sql.includes(';')) throw new Error('一次只能执行一条语句，SQL 里不要出现分号')
  if (!/^(select|with)\b/i.test(sql)) throw new Error('只允许 SELECT 或 WITH 查询')
  if (WRITE_KEYWORD.test(sql)) throw new Error('检测到写操作或危险关键字，本服务只读，已拒绝执行')

  return `SELECT * FROM (${sql}) AS scoder_result LIMIT ${MAX_ROWS}`
}

/** 查询并返回 JSON 文本 */
async function runQuery(raw) {
  const sql = readOnlySql(raw)
  const { rows } = await run(sql)
  if (rows.length === 0) return '查询成功，返回 0 行。'
  return JSON.stringify({ rowCount: rows.length, rows }, null, 2)
}

/** 列出当前库的表 */
async function listTables() {
  const database = connectionSettings().database
  const { rows } = await run(
    `SELECT table_name AS tableName, table_type AS tableType, engine,
            table_rows AS approxRows, table_comment AS comment
     FROM information_schema.tables
     WHERE table_schema = ?
     ORDER BY table_name`,
    [database]
  )
  if (rows.length === 0) {
    return `数据库 ${database} 中没有表，或当前账号看不到它们。`
  }
  return JSON.stringify(rows, null, 2)
}

/** 查看单表字段 */
async function describeTable(table) {
  if (typeof table !== 'string' || !/^[A-Za-z0-9_$]{1,64}$/.test(table)) {
    throw new Error('table 必须是合法的表名（字母、数字、下划线、$，最长 64）')
  }

  const database = connectionSettings().database
  const { rows } = await run(
    `SELECT column_name AS columnName, column_type AS columnType,
            is_nullable AS nullable, column_default AS defaultValue,
            column_key AS columnKey, extra, column_comment AS comment
     FROM information_schema.columns
     WHERE table_schema = ? AND table_name = ?
     ORDER BY ordinal_position`,
    [database, table]
  )
  if (rows.length === 0) {
    throw new Error(`表 ${table} 不存在，或当前账号无权查看`)
  }
  return JSON.stringify(rows, null, 2)
}

/** 结果太长会挤占模型上下文，这里做一次硬截断 */
function clip(text) {
  if (text.length <= MAX_TEXT_CHARS) return text
  return `${text.slice(0, MAX_TEXT_CHARS)}\n…（输出超过 ${MAX_TEXT_CHARS} 字符，已截断；请减少列或用聚合）`
}

/** 统一的成功结果 */
function textResult(text) {
  return { content: [{ type: 'text', text: clip(text) }] }
}

/** 错误转可读文本：保留 MySQL 错误码，方便排查网络 / 权限问题 */
function errorMessage(error) {
  if (error instanceof MySqlError) {
    if (error.errno) return `${error.code} (${error.errno}/${error.sqlState}): ${error.message}`
    return `${error.code}: ${error.message}`
  }
  return error instanceof Error ? error.message : String(error)
}

const tools = [
  {
    name: 'db_list_tables',
    description: '列出当前数据库的表（含大致行数与注释）。只读，不会修改数据。',
    inputSchema: {
      type: 'object',
      properties: {},
      additionalProperties: false
    }
  },
  {
    name: 'db_describe_table',
    description: '查看一张表的字段、类型、是否可空、默认值与索引信息。只读。',
    inputSchema: {
      type: 'object',
      properties: {
        table: { type: 'string', description: '表名，例如 orders' }
      },
      required: ['table'],
      additionalProperties: false
    }
  },
  {
    name: 'db_query',
    description:
      '执行一条只读 SQL（SELECT 或 WITH），最多返回 100 行。适合统计、筛选和聚合；不要写分号。',
    inputSchema: {
      type: 'object',
      properties: {
        sql: {
          type: 'string',
          description: '单条 SELECT / WITH 查询，例如 SELECT * FROM orders LIMIT 5'
        }
      },
      required: ['sql'],
      additionalProperties: false
    }
  }
]

async function callTool(name, args) {
  try {
    switch (name) {
      case 'db_list_tables':
        return textResult(await listTables())
      case 'db_describe_table':
        return textResult(await describeTable(args.table))
      case 'db_query':
        return textResult(await runQuery(args.sql))
      default:
        throw new Error(`未知工具：${name}`)
    }
  } catch (error) {
    return {
      isError: true,
      content: [{ type: 'text', text: `执行失败：${errorMessage(error)}` }]
    }
  }
}

const server = createServer({
  name: 'scoder-mcp-mysql',
  version: '0.2.0',
  instructions:
    '这是一个只读 MySQL 数据库。先用 db_list_tables 看有哪些表，再用 db_describe_table 看字段，' +
    '最后用 db_query 执行 SELECT；db_query 只接受单条 SELECT / WITH，最多返回 100 行。' +
    '不确定表名或字段时不要猜，先查 information_schema 对应的工具。',
  tools,
  callTool
})

/** 关闭连接：否则池里的 socket 会让子进程一直不退出 */
let closing = false
async function shutdown() {
  if (closing) return
  closing = true
  if (connection) await connection.end().catch(() => undefined)
  process.exit(0)
}

process.on('SIGINT', () => void shutdown())
process.on('SIGTERM', () => void shutdown())
process.stdin.on('end', () => void shutdown())

// 配置错误要在进入 MCP 握手前失败：scoder 的状态卡会直接显示“连接失败”
let startup
try {
  startup = connectionSettings()
} catch (error) {
  console.error(`[mcp-mysql] 配置错误：${errorMessage(error)}`)
  process.exit(1)
}

server.start()
console.error(
  `[mcp-mysql] MySQL MCP 服务已启动（零依赖）：${startup.host}:${startup.port}/${startup.database}（只读）`
)
", "file_path": "mysql-server-nodeps.mjs"}

{"content": "#!/usr/bin/env node
/**
 * 假的 MySQL 服务端（零依赖），只为离线自测 mysql-wire.mjs / mysql-server-nodeps.mjs。
 *
 * 支持：协议 4.1 握手、mysql_native_password、caching_sha2_password（快速认证 + RSA 完整认证）、
 *       COM_QUERY 的固定结果集、COM_QUIT。故意不实现写操作：任何非 SELECT 都会被拒绝。
 *
 * 单独运行（把 mysql-server-nodeps.mjs 指过来手玩）：
 *   node mock-mysql.mjs --port 33306 --plugin caching_sha2_password
 */

import net from 'node:net'
import { generateKeyPairSync, createHash } from 'node:crypto'

const CAP = {
  LONG_PASSWORD: 0x00000001,
  FOUND_ROWS: 0x00000002,
  LONG_FLAG: 0x00000004,
  CONNECT_WITH_DB: 0x00000008,
  PROTOCOL_41: 0x00000200,
  TRANSACTIONS: 0x00002000,
  SECURE_CONNECTION: 0x00008000,
  MULTI_RESULTS: 0x00020000,
  PLUGIN_AUTH: 0x00080000
}

const TYPE_LONG = 3
const TYPE_VAR_STRING = 253
const TYPE_LONGLONG = 8
const NOT_NULL = 1

const sha1 = (b) => createHash('sha1').update(b).digest()
const sha256 = (b) => createHash('sha256').update(b).digest()

function xor(a, b) {
  const out = Buffer.allocUnsafe(Math.min(a.length, b.length))
  for (let i = 0; i < out.length; i += 1) out[i] = a[i] ^ b[i]
  return out
}

const lenEnc = (value) => {
  if (value < 0xfb) return Buffer.from([value])
  if (value < 0x10000) {
    const buf = Buffer.allocUnsafe(3)
    buf[0] = 0xfc
    buf.writeUInt16LE(value, 1)
    return buf
  }
  const buf = Buffer.allocUnsafe(4)
  buf[0] = 0xfd
  buf.writeUIntLE(value, 1, 3)
  return buf
}

const lenEncStr = (text) => {
  const body = Buffer.from(text, 'utf8')
  return Buffer.concat([lenEnc(body.length), body])
}

function frame(payload, seq) {
  const header = Buffer.allocUnsafe(4)
  header.writeUIntLE(payload.length, 0, 3)
  header[3] = seq
  return Buffer.concat([header, payload])
}

function okPacket(seq) {
  const payload = Buffer.alloc(7)
  payload[0] = 0x00
  payload[1] = 0
  payload[2] = 0
  payload.writeUInt16LE(0x0002, 3)
  payload.writeUInt16LE(0, 5)
  return frame(payload, seq)
}

function errorPacket(seq, errno, sqlState, message) {
  const payload = Buffer.concat([
    Buffer.from([0xff]),
    (() => {
      const buf = Buffer.allocUnsafe(2)
      buf.writeUInt16LE(errno, 0)
      return buf
    })(),
    Buffer.from(`#${sqlState}`, 'utf8'),
    Buffer.from(message, 'utf8')
  ])
  return frame(payload, seq)
}

function eofPacket(seq) {
  const payload = Buffer.alloc(5)
  payload[0] = 0xfe
  payload.writeUInt16LE(0, 1)
  payload.writeUInt16LE(0x0002, 3)
  return frame(payload, seq)
}

function columnPacket(seq, name, type = TYPE_VAR_STRING) {
  const payload = Buffer.concat([
    lenEncStr('def'), // catalog
    lenEncStr('demo'), // schema
    lenEncStr('demo_table'), // table
    lenEncStr('demo_table'), // org_table
    lenEncStr(name), // name
    lenEncStr(name), // org_name
    Buffer.from([0x0c]), // 固定字段长度
    Buffer.from([0x2d, 0x00]), // charset 45
    (() => {
      const buf = Buffer.allocUnsafe(4)
      buf.writeUInt32LE(1024, 0)
      return buf
    })(),
    Buffer.from([type]),
    (() => {
      const buf = Buffer.allocUnsafe(2)
      buf.writeUInt16LE(type === TYPE_LONG ? 0 : 0, 0)
      return buf
    })(),
    Buffer.from([0x00]),
    Buffer.from([0x00, 0x00])
  ])
  return frame(payload, seq)
}

function rowPacket(seq, values) {
  const parts = values.map((value) => (value === null ? Buffer.from([0xfb]) : lenEncStr(String(value))))
  return frame(Buffer.concat(parts), seq)
}

/** 一次性发完整个结果集，序号从 1 开始递增 */
function resultSet(columns, rows) {
  const chunks = [lenEnc(columns.length)]
  let seq = 1
  const packets = []
  packets.push(frame(chunks[0], seq++))
  for (const [name, type] of columns) packets.push(columnPacket(seq++, name, type))
  packets.push(eofPacket(seq++))
  for (const row of rows) packets.push(rowPacket(seq++, row))
  packets.push(eofPacket(seq++))
  return packets
}

/** 固定演示数据：一个 orders 表 */
const TABLES = [{ tableName: 'orders', tableType: 'BASE TABLE' }]
const DEMO_ROWS = [
  { id: 1, channel: 'app', amount: '199.00', created_at: '2025-06-01 10:00:00' },
  { id: 2, channel: 'web', amount: '59.90', created_at: '2025-06-02 11:30:00' }
]

function answerQuery(sql) {
  const text = sql.toLowerCase()

  if (text.includes('information_schema.tables')) {
    return resultSet(
      [
        ['tableName', TYPE_VAR_STRING],
        ['tableType', TYPE_VAR_STRING],
        ['engine', TYPE_VAR_STRING],
        ['approxRows', TYPE_LONGLONG],
        ['comment', TYPE_VAR_STRING]
      ],
      [['orders', 'BASE TABLE', 'InnoDB', 2, '订单表']]
    )
  }

  if (text.includes('information_schema.columns')) {
    return resultSet(
      [
        ['columnName', TYPE_VAR_STRING],
        ['columnType', TYPE_VAR_STRING],
        ['nullable', TYPE_VAR_STRING],
        ['defaultValue', TYPE_VAR_STRING],
        ['columnKey', TYPE_VAR_STRING],
        ['extra', TYPE_VAR_STRING],
        ['comment', TYPE_VAR_STRING]
      ],
      [
        ['id', 'bigint', 'NO', null, 'PRI', 'auto_increment', '主键'],
        ['channel', 'varchar(32)', 'NO', null, '', '', '渠道'],
        ['amount', 'decimal(12,2)', 'NO', null, '', '', '金额'],
        ['created_at', 'datetime', 'NO', null, '', '', '创建时间']
      ]
    )
  }

  if (text.includes('select version()')) {
    return resultSet([['version()', TYPE_VAR_STRING]], [['8.0.33-mock']])
  }

  // 默认返回演示数据。如果 SQL 里带 WHERE / 聚合，mock 不解析，原样返回两行，
  // 但会检查客户端确实把 ? 换成了字面量（防止把参数当字符串拼进 SQL 的问题被掩盖）。
  const columns = Object.keys(DEMO_ROWS[0]).map((name) => [name, name === 'id' ? TYPE_LONG : TYPE_VAR_STRING])
  return resultSet(
    columns,
    DEMO_ROWS.map((row) => Object.values(row))
  )
}

/** 读取握手响应里的用户、库名、认证响应 */
function parseHandshakeResponse(payload) {
  const capabilities = payload.readUInt32LE(0)
  let offset = 32
  const end = payload.indexOf(0, offset)
  const user = payload.toString('utf8', offset, end)
  offset = end + 1
  const authLen = payload[offset]
  offset += 1
  const authResponse = payload.subarray(offset, offset + authLen)
  offset += authLen
  let database = ''
  if (capabilities & CAP.CONNECT_WITH_DB) {
    const dbEnd = payload.indexOf(0, offset)
    database = payload.toString('utf8', offset, dbEnd)
    offset = dbEnd + 1
  }
  let plugin = ''
  if (capabilities & CAP.PLUGIN_AUTH) {
    const pluginEnd = payload.indexOf(0, offset)
    plugin = payload.toString('utf8', offset, pluginEnd === -1 ? payload.length : pluginEnd)
  }
  return { capabilities, user, authResponse, database, plugin }
}

/**
 * 启动假 MySQL 服务端。
 * @param {object} [options]
 * @param {string} [options.host] 默认 127.0.0.1
 * @param {number} [options.port] 默认 0（随机端口）
 * @param {string} [options.user] 默认 demo
 * @param {string} [options.password] 默认 demo
 * @param {string} [options.database] 默认 demo
 * @param {'mysql_native_password'|'caching_sha2_password'} [options.plugin]
 * @param {boolean} [options.requireFullAuth] caching_sha2 是否强制走 RSA 完整认证
 */
export async function createMockServer(options = {}) {
  const {
    host = '127.0.0.1',
    port = 0,
    user = 'demo',
    password = 'demo',
    database = 'demo',
    plugin = 'mysql_native_password',
    requireFullAuth = false
  } = options

  const { publicKey, privateKey } = generateKeyPairSync('rsa', {
    modulusLength: 2048,
    publicKeyEncoding: { type: 'spki', format: 'pem' },
    privateKeyEncoding: { type: 'pkcs8', format: 'pem' }
  })

  const stats = { connections: 0, queries: [], authPlugins: [] }

  const server = net.createServer((socket) => {
    stats.connections += 1
    socket.on('error', () => socket.destroy())

    const nonce = Buffer.from(
      // 20 字节挑战码，去掉易出问题的 0x00 结尾
      Array.from({ length: 20 }, (_, i) => 1 + ((Math.random() * 250) | 0) + (i % 3)).map((n) => n & 0x7f)
    )

    let capabilities =
      CAP.LONG_PASSWORD | CAP.FOUND_ROWS | CAP.LONG_FLAG | CAP.PROTOCOL_41 | CAP.SECURE_CONNECTION | CAP.MULTI_RESULTS | CAP.PLUGIN_AUTH
    capabilities |= CAP.CONNECT_WITH_DB

    const scramble1 = nonce.subarray(0, 8)
    const scramble2 = Buffer.concat([nonce.subarray(8, 20), Buffer.from([0])])

    const greeting = Buffer.concat([
      Buffer.from([0x0a]),
      Buffer.from('8.0.33-mock\0', 'utf8'),
      (() => {
        const buf = Buffer.allocUnsafe(4)
        buf.writeUInt32LE(1, 0)
        return buf
      })(),
      scramble1,
      Buffer.from([0]),
      (() => {
        const buf = Buffer.allocUnsafe(2)
        buf.writeUInt16LE(capabilities & 0xffff, 0)
        return buf
      })(),
      Buffer.from([45]), // charset
      Buffer.from([0x02, 0x00]), // status
      (() => {
        const buf = Buffer.allocUnsafe(2)
        buf.writeUInt16LE((capabilities >>> 16) & 0xffff, 0)
        return buf
      })(),
      Buffer.from([21]), // auth plugin data len
      Buffer.alloc(10),
      scramble2,
      Buffer.from(`${plugin}\0`, 'utf8')
    ])

    let buffer = Buffer.alloc(0)
    let stage = 'handshake'
    let nextSeq = 0
    let state = { authenticated: false, plugin }

    const send = (buf) => socket.write(buf)

    const onData = (chunk) => {
      buffer = Buffer.concat([buffer, chunk])
      while (buffer.length >= 4) {
        const length = buffer.readUIntLE(0, 3)
        if (buffer.length < 4 + length) break
        const seq = buffer[3]
        const payload = buffer.subarray(4, 4 + length)
        buffer = buffer.subarray(4 + length)
        handlePacket(payload, seq)
      }
    }

    const handlePacket = (payload, seq) => {
      if (stage === 'handshake') {
        const response = parseHandshakeResponse(payload)
        stats.authPlugins.push(response.plugin || state.plugin)
        if (response.user !== user || response.database !== database) {
          send(errorPacket(seq + 1, 1045, '28000', `Access denied for user '${response.user}'@'${host}'`))
          socket.end()
          return
        }

        const expected =
          state.plugin === 'caching_sha2_password'
            ? xor(sha256(Buffer.from(password, 'utf8')), sha256(Buffer.concat([sha256(sha256(Buffer.from(password, 'utf8'))), nonce])))
            : xor(sha1(Buffer.from(password, 'utf8')), sha1(Buffer.concat([nonce, sha1(sha1(Buffer.from(password, 'utf8')))])))

        if (Buffer.compare(expected, response.authResponse) !== 0) {
          send(errorPacket(seq + 1, 1045, '28000', 'Access denied：密码不匹配'))
          socket.end()
          return
        }

        if (state.plugin === 'caching_sha2_password' && requireFullAuth) {
          // 要求完整认证：0x01 0x04
          send(frame(Buffer.from([0x01, 0x04]), seq + 1))
          stage = 'full-auth'
          return
        }

        if (state.plugin === 'caching_sha2_password') {
          // 快速认证成功：0x01 0x03，然后 OK
          send(frame(Buffer.from([0x01, 0x03]), seq + 1))
          send(okPacket(seq + 2))
        } else {
          send(okPacket(seq + 1))
        }
        state.authenticated = true
        stage = 'query'
        return
      }

      if (stage === 'full-auth') {
        if (payload[0] === 0x02) {
          // 客户端要公钥
          send(frame(Buffer.concat([Buffer.from([0x01]), Buffer.from(publicKey, 'utf8')]), seq + 1))
          return
        }
        // RSA-OAEP 解密后应与 password\0 XOR nonce 一致
        try {
          const decrypted = require('node:crypto').privateDecrypt(
            {
              key: privateKey,
              padding: require('node:crypto').constants.RSA_PKCS1_OAEP_PADDING,
              oaepHash: 'sha1'
            },
            payload
          )
          const plain = Buffer.from(`${password}\0`, 'utf8')
          let ok = decrypted.length === plain.length
          if (ok) {
            for (let i = 0; i < plain.length; i += 1) {
              if ((decrypted[i] ^ nonce[i % nonce.length]) !== plain[i]) {
                ok = false
                break
              }
            }
          }
          if (!ok) {
            send(errorPacket(seq + 1, 1045, '28000', 'Access denied：RSA 完整认证失败'))
            socket.end()
            return
          }
          send(okPacket(seq + 1))
          state.authenticated = true
          stage = 'query'
        } catch (error) {
          send(errorPacket(seq + 1, 1045, '28000', `RSA 解密失败：${error.message}`))
          socket.end()
        }
        return
      }

      // COM_QUERY
      if (payload[0] === 0x01) {
        socket.end(okPacket(seq + 1))
        return
      }
      if (payload[0] !== 0x03) {
        send(errorPacket(seq + 1, 1047, '08S01', `mock 不支持的 command 0x${payload[0].toString(16)}`))
        return
      }
      const sql = payload.toString('utf8', 1)
      stats.queries.push(sql)

      if (/\b(insert|update|delete|drop|alter|create|truncate)\b/i.test(sql)) {
        send(errorPacket(seq + 1, 1142, '42000', 'mock 服务端只接受 SELECT'))
        return
      }
      if (sql.includes('boom')) {
        send(errorPacket(seq + 1, 1146, '42S02', "Table 'demo.boom' doesn't exist"))
        return
      }
      for (const packet of answerQuery(sql)) send(packet)
    }

    socket.on('data', onData)
    send(frame(greeting, nextSeq))
  })

  await new Promise((resolve, reject) => {
    server.once('error', reject)
    server.listen(port, host, () => resolve())
  })

  return {
    host,
    port: server.address().port,
    stats,
    close: () =>
      new Promise((resolve) => {
        server.close(() => resolve())
      })
  }
}

