{"content": "#!/usr/bin/env node
/**
 * 用**零依赖**的 MCP 客户端验证 mysql-server-nodeps.mjs，不需要 npm install。
 *
 *   node verify-nodeps.mjs --mock                        # 离线：内置假 MySQL，三种认证各跑一遍
 *   node verify-nodeps.mjs                               # 连真实库（读 MCP_DB_* 环境变量）
 *   node verify-nodeps.mjs --host 10.0.0.12 --user ro --password secret --database app
 *
 * 退出码 0 表示通过，非 0 表示失败（可直接用于 CI）。
 */

import assert from 'node:assert/strict'
import { spawn } from 'node:child_process'
import { dirname, join } from 'node:path'
import { fileURLToPath } from 'node:url'
import { createInterface } from 'node:readline'
import { createMockServer } from './mock-mysql.mjs'

const HERE = dirname(fileURLToPath(import.meta.url))
const SERVER = join(HERE, 'mysql-server-nodeps.mjs')
const PROTOCOL_VERSION = '2025-06-18'

function argValue(args, name, fallback) {
  const index = args.indexOf(`--${name}`)
  return index >= 0 ? args[index + 1] : fallback
}

/** 极简 MCP stdio 客户端：一行一条 JSON-RPC，按 id 匹配响应 */
class MiniClient {
  constructor(env) {
    this.child = spawn(process.execPath, [SERVER], {
      env: { ...process.env, ...env },
      stdio: ['pipe', 'pipe', 'pipe']
    })
    this.nextId = 1
    this.pending = new Map()
    this.stderr = []
    this.exited = false

    createInterface({ input: this.child.stderr, crlfDelay: Infinity }).on('line', (line) => {
      this.stderr.push(line)
      if (process.env.VERIFY_DEBUG) console.error(`  [server] ${line}`)
    })

    createInterface({ input: this.child.stdout, crlfDelay: Infinity }).on('line', (line) => {
      const text = line.trim()
      if (!text) return
      let message
      try {
        message = JSON.parse(text)
      } catch {
        throw new Error(`服务端 stdout 出现非 JSON 数据（stdio 下这是错误）：${text}`)
      }
      if (message.id === undefined || message.id === null) return
      const waiter = this.pending.get(message.id)
      if (!waiter) return
      this.pending.delete(message.id)
      if (message.error) waiter.reject(new Error(`JSON-RPC 错误 ${message.error.code}: ${message.error.message}`))
      else waiter.resolve(message.result)
    })

    this.child.on('exit', (code) => {
      this.exited = true
      for (const waiter of this.pending.values()) {
        waiter.reject(new Error(`服务端进程退出（code=${code}）：${this.stderr.join(' | ')}`))
      }
      this.pending.clear()
    })
  }

  request(method, params) {
    const id = this.nextId++
    const payload = { jsonrpc: '2.0', id, method, ...(params === undefined ? {} : { params }) }
    this.child.stdin.write(`${JSON.stringify(payload)}\n`)
    return new Promise((resolve, reject) => {
      this.pending.set(id, { resolve, reject })
      setTimeout(() => {
        if (this.pending.delete(id)) reject(new Error(`${method} 超时（30s）`))
      }, 30_000).unref()
    })
  }

  notify(method, params) {
    this.child.stdin.write(`${JSON.stringify({ jsonrpc: '2.0', method, ...(params ? { params } : {}) })}\n`)
  }

  async close() {
    if (this.exited) return
    this.child.stdin.end()
    await new Promise((resolve) => {
      const timer = setTimeout(() => {
        this.child.kill()
        resolve()
      }, 3_000)
      this.child.once('exit', () => {
        clearTimeout(timer)
        resolve()
      })
    })
  }
}

const textOf = (result) => (result.content ?? []).filter((b) => b.type === 'text').map((b) => b.text).join('\n')

async function callTool(client, name, args) {
  const result = await client.request('tools/call', { name, arguments: args })
  return { result, text: textOf(result) }
}

async function callOk(client, name, args) {
  const { result, text } = await callTool(client, name, args)
  assert.equal(result.isError, undefined, `${name} 应成功，实际失败：${text}`)
  return text
}

async function callFail(client, name, args, reason) {
  const { result, text } = await callTool(client, name, args)
  assert.equal(result.isError, true, `${name} 应失败（${reason}），实际成功`)
  return text
}

/** 起一个服务端连接，跑完断言后关闭 */
async function withClient(env, task) {
  const client = new MiniClient(env)
  try {
    const init = await client.request('initialize', {
      protocolVersion: PROTOCOL_VERSION,
      capabilities: {},
      clientInfo: { name: 'verify-nodeps', version: '1.0.0' }
    })
    client.notify('notifications/initialized')
    await task(client, init)
  } finally {
    await client.close()
  }
}

async function checkProtocol(init) {
  assert.equal(init.protocolVersion, PROTOCOL_VERSION, '应回显客户端请求的协议版本')
  assert.equal(init.serverInfo?.name, 'scoder-mcp-mysql', 'serverInfo.name')
  assert.ok(init.capabilities?.tools, '应声明 tools 能力')
  assert.match(init.instructions ?? '', /只读/, 'instructions 应说明只读')
  console.log(`✓ initialize：${init.serverInfo.name} ${init.serverInfo.version}（协议 ${init.protocolVersion}）`)
}

/** 通用工具契约检查：清单 + 三个工具的正常/异常路径 */
async function checkTools(client, { expectRealData }) {
  const { tools } = await client.request('tools/list')
  assert.deepEqual(
    tools.map((tool) => tool.name).sort(),
    ['db_describe_table', 'db_list_tables', 'db_query'],
    '应暴露三个只读工具'
  )
  for (const tool of tools) {
    assert.equal(tool.inputSchema?.type, 'object', `${tool.name} 应有 JSON Schema`)
    assert.ok(tool.description?.length > 0, `${tool.name} 应有 description`)
  }
  console.log(`✓ tools/list：${tools.map((t) => t.name).join(', ')}`)

  const tables = await callOk(client, 'db_list_tables', {})
  assert.match(tables, /orders/, 'db_list_tables 应包含 orders 表')
  console.log('✓ db_list_tables 正常返回')

  const described = await callOk(client, 'db_describe_table', { table: 'orders' })
  assert.match(described, /amount/, 'db_describe_table 应包含 amount 字段')
  console.log('✓ db_describe_table 正常返回')

  const badTable = await callFail(client, 'db_describe_table', { table: 'orders; DROP TABLE x' }, '非法表名应被拒绝')
  assert.match(badTable, /合法的表名/, '非法表名的错误应可读')
  console.log(`✓ 非法表名被拒绝：${badTable}`)

  const queried = await callOk(client, 'db_query', { sql: "SELECT id, channel, amount FROM orders WHERE channel = 'app'" })
  assert.match(queried, /"rowCount"/, 'db_query 应返回 rowCount')
  if (expectRealData) assert.match(queried, /app/, '真实库结果应包含渠道 app')
  console.log('✓ db_query 正常返回：')
  console.log(queried.split('\n').slice(0, 8).map((l) => `  ${l}`).join('\n'))

  // 只读边界
  const rawWrite = await callFail(client, 'db_query', { sql: 'DELETE FROM orders' }, '写 SQL 应被拒绝')
  assert.match(rawWrite, /只允许 SELECT 或 WITH/, '写 SQL 的拒绝原因应明确')
  console.log(`✓ 写 SQL 被拒绝：${rawWrite}`)

  const multi = await callFail(client, 'db_query', { sql: 'SELECT 1; DROP TABLE orders' }, '多语句应被拒绝')
  assert.match(multi, /分号/, '多语句的拒绝原因应明确')
  console.log(`✓ 多语句被拒绝：${multi}`)

  const dangerous = await callFail(client, 'db_query', { sql: 'SELECT * FROM orders FOR UPDATE' }, '危险关键字应被拒绝')
  assert.match(dangerous, /危险关键字/, '危险关键字的拒绝原因应明确')
  console.log(`✓ 危险关键字被拒绝：${dangerous}`)

  const unknown = await callFail(client, 'db_query', { sql: 'boom' }, '非 SELECT 应被拒绝')
  assert.match(unknown, /只允许 SELECT 或 WITH/, '非 SELECT 的拒绝原因应明确')
  console.log(`✓ 非 SELECT 被拒绝：${unknown}`)

  // 客户端侧占位转义：引号必须被转义，不能拼成新语句
  const injected = await callOk(client, 'db_query', { sql: "SELECT 'x' AS v WHERE 'a''b' = ?" })
  assert.match(injected, /"v"/, '带占位符的查询应执行成功')
  console.log('✓ 参数占位转义正常')

  const escapeCheck = await callFail(
    client,
    'db_query',
    { sql: 'SELECT * FROM orders WHERE id = 1 OR 1=1 -- ' },
    '注释注入不应绕过只读校验'
  )
  console.log(`✓ 注释注入被拒绝：${escapeCheck.slice(0, 60)}`)
}

async function runMockSuite() {
  const cases = [
    { name: 'mysql_native_password', options: { plugin: 'mysql_native_password' } },
    { name: 'caching_sha2_password（快速认证）', options: { plugin: 'caching_sha2_password' } },
    { name: 'caching_sha2_password（RSA 完整认证）', options: { plugin: 'caching_sha2_password', requireFullAuth: true } }
  ]

  for (const testCase of cases) {
    console.log(`\n=== 假 MySQL：${testCase.name} ===`)
    const mock = await createMockServer(testCase.options)
    try {
      await withClient(
        {
          MCP_DB_HOST: mock.host,
