/** 参数转义的单元级检查：值里的引号必须被转义，不能拼成新语句 */
function checkEscaping() {
  const cases = [
    ["SELECT * FROM t WHERE name = ?", ["a'b"], "'a\\'b'"],
    ['SELECT * FROM t WHERE name = ?', ['a\\'], "'a\\\\'"],
    ['SELECT * FROM t WHERE n = ?', [null], 'NULL'],
    ['SELECT * FROM t WHERE n = ?', [42], '42'],
    ['SELECT * FROM t WHERE n = ?', [true], '1']
  ]
  for (const [sql, values, expected] of cases) {
    const out = internals.interpolate(sql, values)
    assert.ok(out.includes(expected), `转义结果应包含 ${expected}，实际：${out}`)
  }
  // 字符串字面量里的 ? 不能被替换
  assert.equal(internals.interpolate("SELECT '?' AS a, ? AS b", ['x']), "SELECT '?' AS a, 'x' AS b")
  // 参数个数不匹配要报错
  assert.throws(() => internals.interpolate('SELECT ?', []), /占位/)
  assert.throws(() => internals.interpolate('SELECT 1', ['x']), /参数多于/)
  console.log('✓ 参数转义：引号 / 反斜杠 / NULL / 布尔 / 占位个数校验')
